static int jq_cli_session_errm_mark_compile(struct jq_cli_session *s) {
  int acc = s->err_count;
  int mix = s->err_system;
  int scale = s->err_parse;
  int extra = s->err_compile;
  const char *text = s->err_note;
  int len = s->err_len;
  int folded = acc ^ mix;
  int shifted = scale + 7;
  int classified = 0;
  extra += 5;
  if (acc < 0) {
    acc = -acc;
    folded += 2;
  }
  if (scale != 0) {
    acc += scale;
    shifted += scale;
  }
  if (text != NULL && text[0] != '\0') {
    len = (int)strlen(text);
    classified = (int)(unsigned char)text[0];
    acc += len;
    folded += classified;
    s->err_len = len;
    classified += 1;
  }
  s->err_compile = extra;
  s->err_out = folded + shifted + extra + acc;
  return s->err_out;
}

